definition.script:
pipeline {
    agent any

    triggers {
        pollSCM('H/15 * * * *')
    }

    options {
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timestamps()
        timeout(time: 15, unit: 'MINUTES')
    }

    stages {
        stage('Checkout') {
            steps {
                echo 'Checking out develop branch from repository...'
                git branch: 'develop', url: 'https://github.com/SrishtiYadav1904/containerized-mobile-plan-recommendation-platform.git'
            }
        }

        stage('Compile and Test') {
            steps {
                echo 'Compiling source code and executing unit/integration tests...'
                bat '''
                    if exist mvnw.cmd (
                        call mvnw.cmd -B clean test
                    ) else (
                        call "C:\\Users\\Shreyas\\apache-maven-3.9.9\\bin\\mvn.cmd" -B clean test
                    )
                '''
            }
        }

        stage('Package') {
            steps {
                echo 'Packaging application artifact...'
                bat '''
                    if exist mvnw.cmd (
                        call mvnw.cmd -B package -DskipTests
                    ) else (
                        call "C:\\Users\\Shreyas\\apache-maven-3.9.9\\bin\\mvn.cmd" -B package -DskipTests
                    )
                '''
            }
        }
    }

    post {
        always {
            junit allowEmptyResults: true, testResults: 'target/surefire-reports/*.xml'
            archiveArtifacts allowEmptyArchive: true, artifacts: 'target/*.war,target/*.jar', fingerprint: true
        }
        success {
            echo '========================================================'
            echo 'CI Pipeline completed successfully! Artifacts archived.'
            echo '========================================================'
        }
        failure {
            echo '========================================================'
            echo 'CI Pipeline failed. Please inspect logs.'
            echo '========================================================'
        }
    }
}
